}
.kanban-plugin__lane-header-wrapper {
  padding: 0 8px;
  border-bottom: none;
}
.kanban-plugin__lane-header-wrapper .kanban-plugin__lane-grip {
  margin-right: 4px;
  margin-left: -4px;
  padding: 4px;
  border-radius: var(--radius-s);
}
.kanban-plugin__lane-header-wrapper .kanban-plugin__lane-grip:hover {
