}
.kanban-plugin__item-content-wrapper {
  background: transparent;
}
.kanban-plugin__item-title-wrapper {
  padding: 8px;
  background: transparent;
}
.kanban-plugin__item button.kanban-plugin__item-postfix-button {
  opacity: 1;
